ken", "f": {"text": "Berechne den Vektor von A(0 | −3) nach B(−5 | 2).", "schablone": "(□ | □)", "hinweis": "Trage beide Zahlen ein."}, "w": "Ende minus Anfang: (−5 − 0 | 2 − (−3)) = (−5 | 5).", "o": {"werte": [-5, 5]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(1 | 1) mit dem Vektor (3 | 4). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (1 + 3 | 1 + 4) = (4 | 5).", "o": {"werte": [4, 5]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(−2 | 5) mit dem Vektor (6 | −1). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (−2 + 6 | 5 + (−1)) = (4 | 4).", "o": {"werte": [4, 4]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(4 | −3) mit dem Vektor (−4 | 2). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (4 + (−4) | −3 + 2) = (0 | −1).", "o": {"werte": [0, -1]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(0 | 2) mit dem Vektor (5 | 5). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (0 + 5 | 2 + 5) = (5 | 7).", "o": {"werte": [5, 7]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(−1 | −1) mit dem Vektor (2 | −3). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (−1 + 2 | −1 + (−3)) = (1 | −4).", "o": {"werte": [1, -4]}}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Verschiebe P(3 | 0) mit dem Vektor (−2 | 6). Wo liegt P′?", "schablone": "P′(□ | □)", "hinweis": "Trage x und y ein."}, "w": "P′ = (3 + (−2) | 0 + 6) = (1 | 6).", 