-- Thema 91 (raum.schraegbilder), Einheit 30: Etappe koerper_symmetrie „Symmetrie von Körpern“ – 22 Aufgaben (uebung 12, test 1, korrektur 3, sicherung 6)
do $lk$
declare v_status text; v_inhalt jsonb; v_max int; v_auf jsonb; v_n int; v_geteilt boolean;
begin
  select status, inhalt into v_status, v_inhalt from schule.einheit where id = 30 and thema_id = 91;
  if v_status is null then raise exception 'Einheit 30 gehört nicht zu Thema 91'; end if;
  if (select schluessel from schule.thema where id = 91) <> 'raum.schraegbilder' then raise exception 'Thema 91 ist nicht raum.schraegbilder'; end if;
  -- vor der Teilung einspielen: nach TL-S liegt die Etappe in einem anderen Teil
  if exists (select 1 from information_schema.columns where table_schema = 'schule' and table_name = 'thema' and column_name = 'teil_von') then
    execute 'select exists (select 1 from schule.thema where (teil_stamm = $1 or id = $1) and teil_von is not null)' into v_geteilt using 91::bigint;
    if v_geteilt then raise exception 'Thema 91 ist schon geteilt (TL-S) – dieses SQL gehört VOR die Teilung'; end if;
  end if;
  -- 1. Etappe in der Einheit (Lernkarte, Teilfähigkeit, Vertiefung); nur wenn noch nicht da
  if not exists (select 1 from jsonb_array_elements(coalesce(v_inhalt->'etappen', '[]'::jsonb)) x where x->>'lernziel' = 'koerper_symmetrie') then
    if v_status = 'freigegeben' then update schule.einheit set status = 'geprueft' where id = 30; end if;   -- Schutz nur für diesen Schritt (wie TL-S)
    update schule.einheit set inhalt = jsonb_set(jsonb_set(jsonb_set(inhalt,
        '{etappen}', coalesce(inhalt->'etappen', '[]'::jsonb) || jsonb_build_array($j${"lernziel": "koerper_symmetrie", "titel": "Symmetrie von Körpern", "einstieg": "Eine Schachtel lässt sich so durchschneiden, dass beide Hälften Spiegelbilder sind. Die Schnittfläche heißt Symmetrieebene. Manche Körper haben viele davon, ein Würfel sogar neun.", "woerter": [["Symmetrieebene", "Ebene, die einen Körper in zwei spiegelbildliche Hälften teilt"], ["Symmetriezentrum", "Punkt, an dem der Körper punktgespiegelt auf sich selbst fällt"]], "regel": "Quader (alle Kanten verschieden): ⟦3⟧ Symmetrieebenen. Quadratische Säule: 5. Würfel: 9. Gerade Pyramide mit regelmäßigem n-Eck: n Ebenen. Gerades Prisma mit regelmäßigem n-Eck: n + 1.", "schritte": [{"text": "Quader 6 cm × 4 cm × 2 cm: je eine Ebene parallel zu jedem Flächenpaar, mittig. Das sind 3."}, {"text": "Diagonale Schnitte geben beim Quader keine Spiegelhälften, weil die Seiten verschieden lang sind."}], "fehler": "Beim Quader auch diagonale Ebenen zählen: Die gibt es nur, wenn zwei Kanten ⟦gleich lang⟧ sind (quadratische Säule, Würfel)."}$j$::jsonb)),
        '{teilfaehigkeiten}', coalesce(inhalt->'teilfaehigkeiten', '[]'::jsonb) || jsonb_build_array($j${"k": "koerper_symmetrie", "text": "Symmetrie von Körpern", "lernziele": ["koerper_symmetrie"]}$j$::jsonb)),
        '{bewertung,lernziele_vertiefung}', coalesce(inhalt#>'{bewertung,lernziele_vertiefung}', '[]'::jsonb) || to_jsonb('koerper_symmetrie'::text))
     where id = 30;
    update schule.einheit set status = v_status where id = 30;
    raise notice 'Einheit 30: Etappe koerper_symmetrie angelegt';
  else
    raise notice 'Einheit 30: Etappe koerper_symmetrie schon vorhanden';
  end if;
