n hat sie?"}, "w": "Quadratische Säule: 3 + 2 Diagonalebenen = 5.", "g": "einkleidung", "h": "Zwei Kanten sind gleich lang.", "o": {"wert": 5}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Eine gerade Pyramide mit regelmäßiger Grundfläche hat 5 Symmetrieebenen. Wie viele Ecken hat die Grundfläche?"}, "w": "Bei der Pyramide ist die Zahl der Ebenen gleich n: 5 Ecken.", "g": "umkehr", "h": "n-Eck ⇒ n Ebenen.", "o": {"wert": 5}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Durch welche Linien eines Würfels gehen die 6 diagonalen Symmetrieebenen?"}, "w": "Jede geht durch zwei gegenüberliegende Kanten.", "g": "darstellung", "h": "Schneide den Würfel schräg.", "a": ["durch zwei gegenüberliegende Kanten", "durch zwei benachbarte Ecken", "durch die Mitte einer Fläche", "durch eine einzige Kante"], "o": {"index": 0}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein gerades Prisma mit regelmäßiger Grundfläche hat 9 Symmetrieebenen und ist kein Würfel. Wie viele Ecken hat die Grundfläche?"}, "w": "n + 1 = 9 ⇒ n = 8: ein Achteck.", "g": "rueckwaerts", "h": "Prisma: n + 1 Ebenen.", "o": {"wert": 8}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Warum hat eine Pyramide keine waagrechte Symmetrieebene?"}, "w": "Oben ist eine Spitze, unten eine Fläche – die Hälften sind nicht spiegelgleich.", "g": "begruenden", "h": "Vergleiche oben und unten.", "a": ["Weil Spitze und Grundfläche verschieden sind.", "Weil sie zu wenig Ecken hat.", "Weil sie schief ist.", "Weil sie kein Volumen hat."], "o": {"index": 0}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Mia sagt: „Ein Quader mit 6 cm, 4 cm und 2 cm hat 9 Symmetrieebenen wie der Würfel.“ Was stimmt?"}, "w": "Nur 3: Diagonalebenen gibt es nur bei gleich langen Kanten.", "g": "fehler", "h": "Sind Kanten gleich lang?", "a": ["Falsch: er hat 3.", "Richtig.", "Falsch: er hat 6.", "Falsch: er hat 5."], "o": {"index": 0}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Bleistift ist ein gerades Prisma mit regelmäßigem Sechseck und ohne Spitze. Wie viele Symmetrieebenen hat er zusammen mit der Mittelebene quer?"}, "w": "6 längs + 1 quer = 7.", "g": "transfer", "h": "Längsebenen wie die Sechseck-Achsen.", "o": {"wert": 7}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "test", "s": 2, "y": "zahl", "f": {"text": "Wie viele Symmetrieebenen hat eine quadratische Säule (Grundfläche Quadrat, Höhe anders)?"}, "w": "Quadratische Säule: 3 Ebenen parallel zu den Flächen und 2 diagonale, zusammen 5.", "o": {"wert": 5}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Wie viele Symmetrieebenen hat eine gerade Pyramide mit regelmäßigem 3-Eck als Grundfläche?"}, "w": "Jede der 3 Symmetrieachsen des 3-Ecks gibt eine Ebene durch die Spitze: 3.", "o": {"wert": 3}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Wie viele Symmetrieebenen hat eine gerade Pyramide mit regelmäßigem 4-Eck als Grundfläche?"}, "w": "Jede der 4 Symmetrieachsen des 4-Ecks gibt eine Ebene durch die Spitze: 4.", "o": {"wert": 4}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Wie viele Symmetrieebenen hat eine gerade Pyramide mit regelmäßigem 6-Eck als Grundfläche?"}, "w": "Jede der 6 Symmetrieachsen des 6-Ecks gibt eine Ebene durch die Spitze: 6.", "o": {"wert": 6}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 3-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "3 Ebenen durch die Achsen des 3-Ecks und 1 waagrechte Mittelebene: 4.", "o": {"wert": 4}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 5-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "5 Ebenen durch die Achsen des 5-Ecks und 1 waagrechte Mittelebene: 6.", "o": {"wert": 6}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 6-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "6 Ebenen durch die Achsen des 6-Ecks und 1 waagrechte Mittelebene: 7.", "o": {"wert": 7}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 8-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "8 Ebenen durch die Achsen des 8-Ecks und 1 waagrechte Mittelebene: 9.", "o": {"wert": 9}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 10-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "10 Ebenen durch die Achsen des 10-Ecks und 1 waagrechte Mittelebene: 11.", "o": {"wert": 11}}, {"l": "koerper_symmetrie", "t": "koerper_symmetrie", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges 12-Eck als Grundfläche (Höhe anders als die Seiten). Wie viele Symmetrieebenen hat es?"}, "w": "12 Ebenen durch die Achsen des 12-Ecks und 1 waagrechte Mittelebene: 13.", "o": {"wert": 13}}]$j$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(30, v_auf);
  raise notice 'Einheit 30 (koerper_symmetrie): % von 22 Aufgaben eingefügt (0 = schon vorhanden)', v_n;
  if v_n not in (0, 22) then raise exception 'Einheit 30 (koerper_symmetrie): nur % von 22 eingefügt – teilweise vorhanden, bitte prüfen', v_n; end if;
  -- 3. Kann-Satz
  insert into schule.etappe_text (thema_id, lernziel, kann, geaendert_am) values (91, 'koerper_symmetrie', $j$Symmetrieebenen und Symmetriezentren von Quader, Würfel, Prisma und Pyramide bestimmen$j$, now())
  on conflict (thema_id, lernziel) do nothing;
end $lk$;

-- Thema 91 (raum.schraegbilder), Einheit 30: Etappe raumwinkel „Winkel im Raum“ – 22 Aufgaben (uebung 12, test 1, korrektur 3, sicherung 6)
do $lk$
declare v_status text; v_inhalt jsonb; v_max int; v_auf jsonb; v_n int; v_geteilt boolean;
begin
  select status, inhalt into v_status, v_inhalt from schule.einheit where id = 30 and thema_id = 91;
  if v_status is null then raise exception 'Einheit 30 gehört nicht zu Thema 91'; end if;
  if (select schluessel from schule.thema where id = 91) <> 'raum.schraegbilder' then raise exception 'Thema 91 ist nicht raum.schraegbilder'; end if;
  -- vor der Teilung einspielen: nach TL-S liegt die Etappe in einem anderen Teil
  if exists (select 1 from information_schema.columns where table_schema = 'schule' and table_name = 'thema' and column_name = 'teil_von') then
    execute 'select exists (select 1 from schule.thema where (teil_stamm = $1 or id = $1) and teil_von is not null)' into v_geteilt using 91::bigint;
    if v_geteilt then raise exception 'Thema 91 ist schon geteilt (TL-S) – dieses SQL gehört VOR die Teilung'; end if;
  end if;
  -- 1. Etappe in der Einheit (Lernkarte, Teilfähigkeit, Vertiefung); nur wenn noch nicht da
  if not exists (select 1 from jsonb_array_elements(coalesce(v_inhalt->'etappen', '[]'::jsonb)) x where x->>'lernziel' = 'raumwinkel') then
    if v_status = 'freigegeben' then update schule.einheit set status = 'geprueft' where id = 30; end if;   -- Schutz nur für diesen Schritt (wie TL-S)
    update schule.einheit set inhalt = jsonb_set(jsonb_set(jsonb_set(inhalt,
        '{etappen}', coalesce(inhalt->'etappen', '[]'::jsonb) || jsonb_build_array($j${"lernziel": "raumwinkel", "titel": "Winkel im Raum", "einstieg": "Ein Fahnenmast steht senkrecht auf dem Schulhof, ein Seil führt schräg von der Spitze zum Boden. Zwischen Mast und Boden ist ein rechter Winkel, zwischen Seil und Boden ein spitzer. Solche Winkel im Raum kann man an Körpern ablesen.", "woerter": [["Neigungswinkel", "Winkel zwischen einer Geraden und einer Ebene"], ["Winkel zwischen Ebenen", "Winkel zweier Flächen entlang ihrer gemeinsamen Kante"]], "regel": "Steht eine Kante ⟦senkrecht⟧ auf einer Fläche, bilden beide 90°. Am Quader treffen alle Flächen im rechten Winkel aufeinander. Beim geraden Prisma ist der Winkel zwischen zwei Seitenflächen der Innenwinkel der Grundfläche.", "schritte": [{"text": "Gerades Prisma mit einem gleichseitigen Dreieck als Grundfläche."}, {"text": "Zwei Seitenflächen treffen sich an einer senkrechten Kante. Ihr Winkel ist der Dreieckswinkel: ⟦60°⟧."}, {"text": "Jede Seitenfläche steht senkrecht auf der Grundfläche: 90°."}], "fehler": "Den Winkel im Schrägbild messen: Dort ist der rechte Winkel oft als 45° oder 135° gezeichnet. Im Raum ist er ⟦90°⟧."}$j$::jsonb)),
        '{teilfaehigkeiten}', coalesce(inhalt->'teilfaehigkeiten', '[]'::jsonb) || jsonb_build_array($j${"k": "raumwinkel", "text": "Winkel im Raum", "lernziele": ["raumwinkel"]}$j$::jsonb)),
        '{bewertung,lernziele_vertiefung}', coalesce(inhalt#>'{bewertung,lernziele_vertiefung}', '[]'::jsonb) || to_jsonb('raumwinkel'::text))
     where id = 30;
    update schule.einheit set status = v_status where id = 30;
    raise notice 'Einheit 30: Etappe raumwinkel angelegt';
  else
    raise notice 'Einheit 30: Etappe raumwinkel schon vorhanden';
  end if;
  -- 2. Aufgaben aller Pools (nur INSERT; Vorhandenes wird nicht doppelt eingefügt)
  select coalesce(max(reihenfolge), 0) into v_max from schule.aufgabe where einheit_id = 30;
  select jsonb_agg(x.a || jsonb_build_object('r', v_max + x.nr)) into v_auf
    from jsonb_array_elements($j$[{"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Wie groß ist der Winkel zwischen einer senkrechten Quaderkante und der Grundfläche?"}, "w": "Die Kante steht senkrecht auf der Grundfläche: 90°.", "g": "direkt", "h": "Senkrecht heißt 90°.", "o": {"wert": 90, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein Quadrat als Grundfläche. Unter welchem Winkel treffen zwei benachbarte Seitenflächen aufeinander?"}, "w": "Der Winkel ist der Innenwinkel des Quadrats: 90°.", "g": "direkt", "h": "Schau auf die Grundfläche.", "o": {"wert": 90, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Welcher Winkel ist ein Neigungswinkel?"}, "w": "Ein Neigungswinkel liegt zwischen einer Geraden und einer Ebene, z. B. Seil und Boden.", "g": "erkennen", "h": "Gerade und Ebene.", "a": ["zwischen Seil und Boden", "zwischen zwei Seilen", "zwischen zwei Böden", "zwischen zwei Punkten"], "o": {"index": 0}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Im Schrägbild eines Würfels erscheint die Ecke vorne unten rechts mit 135°. Wie groß ist der Winkel am Würfel?"}, "w": "Am Würfel sind alle Winkel zwischen Kanten 90°; das Schrägbild verzerrt.", "g": "erkennen", "h": "Zeichnung und Körper unterscheiden.", "a": ["90°", "135°", "45°", "180°"], "o": {"index": 0}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges Sechseck als Grundfläche. Wie groß ist der Winkel zwischen zwei benachbarten Seitenflächen?"}, "w": "Innenwinkelsumme Sechseck 720°, ein Winkel 720° : 6 = 120°.", "g": "mehrschritt", "h": "Erst den Innenwinkel des Sechsecks.", "o": {"wert": 120, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein Zelt hat einen dreieckigen Querschnitt mit zwei gleichen Winkeln von 65° am Boden. Wie groß ist der Winkel zwischen den beiden Zeltwänden oben?"}, "w": "180° − 2 · 65° = 50°.", "g": "einkleidung", "h": "Winkelsumme im Dreieck.", "o": {"wert": 50, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Zwei Seitenflächen eines geraden Prismas mit regelmäßiger Grundfläche bilden 108°. Wie viele Ecken hat die Grundfläche?"}, "w": "Regelmäßiges n-Eck mit Innenwinkel 108°: Fünfeck (540° : 5 = 108°).", "g": "umkehr", "h": "Welches regelmäßige Vieleck hat 108°?", "o": {"wert": 5}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Eine Rampe steigt vom Boden an. Welcher Winkel beschreibt, wie steil sie ist?"}, "w": "Der Neigungswinkel zwischen Rampenfläche und Boden.", "g": "darstellung", "h": "Fläche gegen Boden.", "a": ["der Winkel zwischen Rampe und Boden", "der Winkel zwischen zwei Bodenfliesen", "der Winkel am oberen Ende der Rampe zur Wand", "der Winkel zwischen zwei Geländerstäben"], "o": {"index": 0}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "In einem geraden Prisma mit dreieckiger Grundfläche bilden zwei Seitenflächen 70° und 50°. Welchen Winkel bilden die dritte und die zweite Seitenfläche?"}, "w": "Die Winkel zwischen Seitenflächen sind die Dreieckswinkel: 180° − 70° − 50° = 60°.", "g": "rueckwaerts", "h": "Winkelsumme der Grundfläche.", "o": {"wert": 60, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Warum ist der Winkel zwischen zwei Seitenflächen eines geraden Prismas gleich dem Innenwinkel der Grundfläche?"}, "w": "Die Seitenflächen stehen senkrecht auf der Grundfläche; ihr Winkel zeigt sich unverändert in der Grundfläche.", "g": "begruenden", "h": "Schneide waagrecht durch.", "a": ["Weil die Seitenflächen senkrecht auf der Grundfläche stehen.", "Weil alle Kanten gleich lang sind.", "Weil das Prisma symmetrisch ist.", "Weil die Deckfläche kleiner ist."], "o": {"index": 0}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Ben misst im Schrägbild eines Quaders zwischen Vorder- und Seitenfläche 45° und schreibt: „Die Flächen bilden 45°.“ Was stimmt?"}, "w": "Im Schrägbild ist der Winkel verzerrt. Am Quader bilden die Flächen 90°.", "g": "fehler", "h": "Ist ein Quader schief?", "a": ["Falsch: am Quader sind es 90°.", "Richtig.", "Falsch: es sind 135°.", "Falsch: es sind 60°."], "o": {"index": 0}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Dach hat zwei gleich geneigte Flächen. Jede bildet mit dem waagrechten Dachboden 35°. Wie groß ist der Winkel zwischen den beiden Dachflächen am First?"}, "w": "Querschnitt Dreieck: 180° − 2 · 35° = 110°.", "g": "transfer", "h": "Zeichne den Querschnitt.", "o": {"wert": 110, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "test", "s": 2, "y": "zahl", "f": {"text": "Ein gerades Prisma hat ein regelmäßiges Achteck als Grundfläche. Wie groß ist der Winkel zwischen zwei benachbarten Seitenflächen?"}, "w": "Innenwinkel: 1 080° : 8 = 135°.", "o": {"wert": 135, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Zwei gleich geneigte Dachflächen bilden mit dem Dachboden je 40°. Welchen Winkel bilden sie am First?"}, "w": "180° − 2 · 40° = 100°.", "o": {"wert": 100, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Zwei gleich geneigte Dachflächen bilden mit dem Dachboden je 55°. Welchen Winkel bilden sie am First?"}, "w": "180° − 2 · 55° = 70°.", "o": {"wert": 70, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Zwei gleich geneigte Dachflächen bilden mit dem Dachboden je 70°. Welchen Winkel bilden sie am First?"}, "w": "180° − 2 · 70° = 40°.", "o": {"wert": 40, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 3-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 3-Ecks: (3 − 2) · 180° : 3 = 60°.", "o": {"wert": 60, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 4-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 4-Ecks: (4 − 2) · 180° : 4 = 90°.", "o": {"wert": 90, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 5-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 5-Ecks: (5 − 2) · 180° : 5 = 108°.", "o": {"wert": 108, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 6-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 6-Ecks: (6 − 2) · 180° : 6 = 120°.", "o": {"wert": 120, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 9-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 9-Ecks: (9 − 2) · 180° : 9 = 140°.", "o": {"wert": 140, "einheit": "°"}}, {"l": "raumwinkel", "t": "raumwinkel", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Gerades Prisma mit regelmäßigem 10-Eck als Grundfläche: Welchen Winkel bilden zwei benachbarte Seitenflächen?"}, "w": "Innenwinkel des 10-Ecks: (10 − 2) · 180° : 10 = 144°.", "o": {"wert": 144, "einheit": "°"}}]$j$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(30, v_auf);
  raise notice 'Einheit 30 (raumwinkel): % von 22 Aufgaben eingefügt (0 = schon vorhanden)', v_n;
  if v_n not in (0, 22) then raise exception 'Einheit 30 (raumwinkel): nur % von 22 eingefügt – teilweise vorhanden, bitte prüfen', v_n; end if;
  -- 3. Kann-Satz
  insert into schule.etappe_text (thema_id, lernziel, kann, geaendert_am) values (91, 'raumwinkel', $j$Winkel zwischen Kanten, Flächen und Geraden an Prismen und Quadern bestimmen$j$, now())
  on conflict (thema_id, lernziel) do nothing;
end $lk$;

-- Thema 101 (messen.prisma_zylinder), Einheit 94: Etappe cavalieri „Schiefe Körper und Cavalieri“ – 22 Aufgaben (uebung 12, test 1, korrektur 3, sicherung 6)
do $lk$
declare v_status text; v_inhalt jsonb; v_max int; v_auf jsonb; v_n int; v_geteilt boolean;
begin
  select status, inhalt into v_status, v_inhalt from schule.einheit where id = 94 and thema_id = 101;
  if v_status is null then raise exception 'Einheit 94 gehört nicht zu Thema 101'; end if;
  if (select schluessel from schule.thema where id = 101) <> 'messen.prisma_zylinder' then raise exception 'Thema 101 ist nicht messen.prisma_zylinder'; end if;
  -- vor der Teilung einspielen: nach TL-S liegt die Etappe in einem anderen Teil
  if exists (select 1 from information_schema.columns where table_schema = 'schule' and table_name = 'thema' and column_name = 'teil_von') then
    execute 'select exists (select 1 from schule.thema where (teil_stamm = $1 or id = $1) and teil_von is not null)' into v_geteilt using 101::bigint;
    if v_geteilt then raise exception 'Thema 101 ist schon geteilt (TL-S) – dieses SQL gehört VOR die Teilung'; end if;
  end if;
  -- 1. Etappe in der Einheit (Lernkarte, Teilfähigkeit, Vertiefung); nur wenn noch nicht da
  if not exists (select 1 from jsonb_array_elements(coalesce(v_inhalt->'etappen', '[]'::jsonb)) x where x->>'lernziel' = 'cavalieri') then
    if v_status = 'freigegeben' then update schule.einheit set status = 'geprueft' where id = 94; end if;   -- Schutz nur für diesen Schritt (wie TL-S)
    update schule.einheit set inhalt = jsonb_set(jsonb_set(jsonb_set(inhalt,
        '{etappen}', coalesce(inhalt->'etappen', '[]'::jsonb) || jsonb_build_array($j${"lernziel": "cavalieri", "titel": "Schiefe Körper und Cavalieri", "einstieg": "Ein Stapel Bierdeckel steht gerade. Schiebt man ihn schräg, sieht er anders aus – aber es sind dieselben Deckel. Das Volumen bleibt gleich. Genau das sagt das Prinzip von Cavalieri.", "woerter": [["Cavalieri-Prinzip", "gleiche Querschnittsflächen in jeder Höhe und gleiche Höhe ergeben gleiches Volumen"], ["Höhe h", "senkrechter Abstand von Grund- und Deckfläche, nicht die schräge Kante"]], "regel": "Auch für schiefe Prismen und Zylinder gilt ⟦V = G · h⟧. h ist der senkrechte Abstand der beiden Grundflächen, nicht die Länge der schrägen Kante.", "schritte": [{"text": "Ein schiefes Prisma hat G = 12 cm², die schräge Kante ist 10 cm lang, der senkrechte Abstand der Grundflächen 8 cm."}, {"text": "Es zählt die senkrechte Höhe: V = 12 cm² · 8 cm = ⟦96 cm³⟧. Die 10 cm braucht man nicht."}], "fehler": "Mit der schrägen Kante rechnen: 12 · 10 = 120 cm³ ist zu viel. Beim schiefen Körper ⟦nur die senkrechte Höhe⟧ nehmen."}$j$::jsonb)),
        '{teilfaehigkeiten}', coalesce(inhalt->'teilfaehigkeiten', '[]'::jsonb) || jsonb_build_array($j${"k": "cavalieri", "text": "Schiefe Körper und Cavalieri", "lernziele": ["cavalieri"]}$j$::jsonb)),
        '{bewertung,lernziele_vertiefung}', coalesce(inhalt#>'{bewertung,lernziele_vertiefung}', '[]'::jsonb) || to_jsonb('cavalieri'::text))
     where id = 94;
    update schule.einheit set status = v_status where id = 94;
    raise notice 'Einheit 94: Etappe cavalieri angelegt';
  else
    raise notice 'Einheit 94: Etappe cavalieri schon vorhanden';
  end if;
  -- 2. Aufgaben aller Pools (nur INSERT; Vorhandenes wird nicht doppelt eingefügt)
  select coalesce(max(reihenfolge), 0) into v_max from schule.aufgabe where einheit_id = 94;
