    from jsonb_array_elements($j$[{"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Ein schiefes Prisma hat die Grundfläche 15 cm² und die Höhe 6 cm. Berechne das Volumen."}, "w": "V = 15 cm² · 6 cm = 90 cm³.", "g": "direkt", "h": "Grundfläche mal senkrechte Höhe.", "o": {"wert": 90, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat eine Grundfläche von 20 cm² und eine Höhe von 9 cm. Wie groß ist sein Volumen?"}, "w": "V = 20 cm² · 9 cm = 180 cm³.", "g": "direkt", "h": "Wie beim geraden Zylinder.", "o": {"wert": 180, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Welche Länge setzt man beim schiefen Prisma für h ein?"}, "w": "h ist der senkrechte Abstand der Grundflächen.", "g": "erkennen", "h": "Miss senkrecht, nicht entlang der Kante.", "a": ["den senkrechten Abstand der Grundflächen", "die Länge der schrägen Kante", "die längste Seite der Grundfläche", "die Diagonale des Körpers"], "o": {"index": 0}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Ein gerades und ein schiefes Prisma haben dieselbe Grundfläche und dieselbe Höhe. Was gilt?"}, "w": "Nach Cavalieri sind die Volumen gleich.", "g": "erkennen", "h": "Schräg schieben ändert das Volumen nicht.", "a": ["Sie haben dasselbe Volumen.", "Das schiefe hat mehr Volumen.", "Das gerade hat mehr Volumen.", "Man kann es nicht sagen."], "o": {"index": 0}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefes Prisma hat ein Dreieck als Grundfläche (g = 6 cm, h_D = 4 cm). Die Körperhöhe ist 10 cm. Berechne das Volumen."}, "w": "G = 6 · 4 : 2 = 12 cm². V = 12 · 10 = 120 cm³.", "g": "mehrschritt", "h": "Erst die Dreiecksfläche, dann mal Körperhöhe.", "o": {"wert": 120, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein schräger Turm ist ein schiefer Zylinder mit G = 3 m² und 12 m senkrechter Höhe; seine Wand ist 12,5 m lang. Wie viele m³ fasst er?"}, "w": "Es zählt die senkrechte Höhe: V = 3 · 12 = 36 m³.", "g": "einkleidung", "h": "Die Wandlänge ist die schräge Kante.", "o": {"wert": 36, "einheit": "m³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefes Prisma hat 84 cm³ Volumen und 14 cm² Grundfläche. Wie groß ist die Höhe?"}, "w": "h = V : G = 84 : 14 = 6 cm.", "g": "umkehr", "h": "Teile das Volumen durch die Grundfläche.", "o": {"wert": 6, "einheit": "cm"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Zwei Münzstapel mit gleich vielen gleichen Münzen: einer gerade, einer schräg. Welche Aussage trifft zu?"}, "w": "In jeder Höhe liegt eine gleich große Münzfläche, also gleiches Volumen (Cavalieri).", "g": "darstellung", "h": "Vergleiche Schicht für Schicht.", "a": ["gleiches Volumen, weil jede Schicht gleich groß ist", "der schräge Stapel hat mehr Volumen", "der gerade Stapel ist höher", "die Oberflächen sind gleich"], "o": {"index": 0}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein schiefes und ein gerades Prisma haben gleiches Volumen und gleiche Höhe 8 cm. Das gerade hat G = 9 cm². Wie groß ist G beim schiefen?"}, "w": "Gleiches V und gleiches h ⇒ gleiche Grundfläche: 9 cm².", "g": "rueckwaerts", "h": "V = G · h für beide.", "o": {"wert": 9, "einheit": "cm²"}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Warum hat ein schiefes Prisma dieselbe Formel V = G · h wie ein gerades?"}, "w": "Schneidet man beide in gleicher Höhe, sind die Schnittflächen gleich groß (= G). Nach Cavalieri sind die Volumen gleich.", "g": "begruenden", "h": "Denke an die Schnitte parallel zur Grundfläche.", "a": ["Weil die Querschnitte in jeder Höhe gleich groß sind.", "Weil die Kanten gleich lang sind.", "Weil die Oberflächen gleich sind.", "Weil beide gleich viele Ecken haben."], "o": {"index": 0}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Paul berechnet ein schiefes Prisma (G = 10 cm², Kante 13 cm, Höhe 12 cm) so: V = 10 · 13 = 130 cm³. Was stimmt?"}, "w": "Er hat die schräge Kante genommen. Richtig: 10 · 12 = 120 cm³.", "g": "fehler", "h": "Welche Länge ist die Höhe?", "a": ["Falsch: richtig sind 120 cm³.", "Alles richtig.", "Richtig sind 156 cm³.", "Richtig sind 1 560 cm³."], "o": {"index": 0}}, {"l": "cavalieri", "t": "cavalieri", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Tunnelstück verläuft schräg durch einen Berg. Sein Querschnitt ist überall 40 m², der Höhenunterschied der Endflächen senkrecht gemessen 250 m. Wie viel m³ Gestein wurden ausgebrochen?"}, "w": "Wie ein schiefes Prisma: 40 · 250 = 10 000 m³.", "g": "transfer", "h": "Gleicher Querschnitt überall: G · h.", "o": {"wert": 10000, "einheit": "m³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "test", "s": 2, "y": "zahl", "f": {"text": "Ein schiefes Prisma hat G = 18 cm² und h = 5 cm, die schräge Kante ist 6 cm lang. Berechne V."}, "w": "V = 18 · 5 = 90 cm³.", "o": {"wert": 90, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Schiefes Prisma: G = 7 cm², senkrechte Höhe 4 cm, schräge Kante 5 cm. Wie groß ist V?"}, "w": "V = 7 · 4 = 28 cm³; die Kante zählt nicht.", "o": {"wert": 28, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Schiefes Prisma: G = 25 cm², senkrechte Höhe 3 cm, schräge Kante 4 cm. Wie groß ist V?"}, "w": "V = 25 · 3 = 75 cm³; die Kante zählt nicht.", "o": {"wert": 75, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Schiefes Prisma: G = 11 cm², senkrechte Höhe 6 cm, schräge Kante 7 cm. Wie groß ist V?"}, "w": "V = 11 · 6 = 66 cm³; die Kante zählt nicht.", "o": {"wert": 66, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 12 cm² und die Höhe 7 cm. Berechne das Volumen."}, "w": "V = 12 · 7 = 84 cm³.", "o": {"wert": 84, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 30 cm² und die Höhe 2 cm. Berechne das Volumen."}, "w": "V = 30 · 2 = 60 cm³.", "o": {"wert": 60, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 16 cm² und die Höhe 5 cm. Berechne das Volumen."}, "w": "V = 16 · 5 = 80 cm³.", "o": {"wert": 80, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 9 cm² und die Höhe 9 cm. Berechne das Volumen."}, "w": "V = 9 · 9 = 81 cm³.", "o": {"wert": 81, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 40 cm² und die Höhe 3 cm. Berechne das Volumen."}, "w": "V = 40 · 3 = 120 cm³.", "o": {"wert": 120, "einheit": "cm³"}}, {"l": "cavalieri", "t": "cavalieri", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Ein schiefer Zylinder hat G = 22 cm² und die Höhe 4 cm. Berechne das Volumen."}, "w": "V = 22 · 4 = 88 cm³.", "o": {"wert": 88, "einheit": "cm³"}}]$j$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(94, v_auf);
