-- Thema 29 (terme.umformen), Einheit 3: Etappe gleichungen_binomisch „Gleichungen mit Klammerprodukten“ – 22 Aufgaben (uebung 12, test 1, korrektur 3, sicherung 6)
do $lk$
declare v_status text; v_inhalt jsonb; v_max int; v_auf jsonb; v_n int; v_geteilt boolean;
begin
  select status, inhalt into v_status, v_inhalt from schule.einheit where id = 3 and thema_id = 29;
  if v_status is null then raise exception 'Einheit 3 gehört nicht zu Thema 29'; end if;
  if (select schluessel from schule.thema where id = 29) <> 'terme.umformen' then raise exception 'Thema 29 ist nicht terme.umformen'; end if;
  -- vor der Teilung einspielen: nach TL-S liegt die Etappe in einem anderen Teil
  if exists (select 1 from information_schema.columns where table_schema = 'schule' and table_name = 'thema' and column_name = 'teil_von') then
    execute 'select exists (select 1 from schule.thema where (teil_stamm = $1 or id = $1) and teil_von is not null)' into v_geteilt using 29::bigint;
    if v_geteilt then raise exception 'Thema 29 ist schon geteilt (TL-S) – dieses SQL gehört VOR die Teilung'; end if;
  end if;
  -- 1. Etappe in der Einheit (Lernkarte, Teilfähigkeit, Vertiefung); nur wenn noch nicht da
  if not exists (select 1 from jsonb_array_elements(coalesce(v_inhalt->'etappen', '[]'::jsonb)) x where x->>'lernziel' = 'gleichungen_binomisch') then
    if v_status = 'freigegeben' then update schule.einheit set status = 'geprueft' where id = 3; end if;   -- Schutz nur für diesen Schritt (wie TL-S)
    update schule.einheit set inhalt = jsonb_set(jsonb_set(jsonb_set(inhalt,
        '{etappen}', coalesce(inhalt->'etappen', '[]'::jsonb) || jsonb_build_array($j${"lernziel": "gleichungen_binomisch", "titel": "Gleichungen mit Klammerprodukten", "einstieg": "Ein quadratisches Beet wird an jeder Seite um 3 m länger und ist dann 51 m² größer. Wie lang war die Seite? In der Gleichung stehen Klammern mit Quadrat. Nach dem Ausmultiplizieren fällt x² weg.", "regel": "Erst beide Seiten ⟦ausmultiplizieren⟧ (binomische Formeln), dann zusammenfassen. Hebt sich x² auf, bleibt eine lineare Gleichung.", "schritte": [{"text": "(x + 3)² = x² + 51. Links: x² + 6x + 9 = x² + 51."}, {"text": "x² auf beiden Seiten abziehen: 6x + 9 = 51, also 6x = 42 und ⟦x = 7⟧."}], "fehler": "(x + 3)² ist nicht x² + 9. Es fehlt das ⟦Doppelte Produkt⟧ 2 · 3 · x = 6x."}$j$::jsonb)),
        '{teilfaehigkeiten}', coalesce(inhalt->'teilfaehigkeiten', '[]'::jsonb) || jsonb_build_array($j${"k": "gleichungen_binomisch", "text": "Gleichungen mit Klammerprodukten", "lernziele": ["gleichungen_binomisch"]}$j$::jsonb)),
        '{bewertung,lernziele_vertiefung}', coalesce(inhalt#>'{bewertung,lernziele_vertiefung}', '[]'::jsonb) || to_jsonb('gleichungen_binomisch'::text))
     where id = 3;
    update schule.einheit set status = v_status where id = 3;
    raise notice 'Einheit 3: Etappe gleichungen_binomisch angelegt';
  else
    raise notice 'Einheit 3: Etappe gleichungen_binomisch schon vorhanden';
  end if;
