  select jsonb_agg(x.a || jsonb_build_object('r', v_max + x.nr)) into v_auf
    from jsonb_array_elements($j$[{"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Löse (x + 2)² = x² + 20."}, "w": "x² + 4x + 4 = x² + 20 ⇒ 4x = 16 ⇒ x = 4.", "g": "direkt", "h": "Erst (x + 2)² ausmultiplizieren.", "o": {"wert": 4}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 1, "y": "zahl", "f": {"text": "Löse (x − 1)² = x² − 9."}, "w": "x² − 2x + 1 = x² − 9 ⇒ −2x = −10 ⇒ x = 5.", "g": "direkt", "h": "Zweite binomische Formel.", "o": {"wert": 5}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Was ergibt (x + 5)² ausmultipliziert?"}, "w": "Mit a² + 2ab + b²: x² + 2 · 5 · x + 25 = x² + 10x + 25.", "g": "erkennen", "h": "a² + 2ab + b².", "a": ["x² + 10x + 25", "x² + 25", "x² + 5x + 25", "2x + 10"], "o": {"index": 0}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Warum wird (x + 4)² = x² + 40 eine lineare Gleichung?"}, "w": "x² steht auf beiden Seiten und hebt sich auf.", "g": "erkennen", "h": "Was passiert mit x²?", "a": ["x² hebt sich auf beiden Seiten weg.", "Weil 40 gerade ist.", "Weil man die Wurzel zieht.", "Weil x positiv ist."], "o": {"index": 0}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Löse (x + 3)(x − 3) = x² + 2x − 15."}, "w": "x² − 9 = x² + 2x − 15 ⇒ 6 = 2x ⇒ x = 3.", "g": "mehrschritt", "h": "Dritte binomische Formel links.", "o": {"wert": 3}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein quadratisches Feld wird an jeder Seite 2 m länger und dadurch 36 m² größer. Wie lang war die Seite (in m)?"}, "w": "(x + 2)² = x² + 36 ⇒ 4x + 4 = 36 ⇒ x = 8.", "g": "einkleidung", "h": "Stelle (x + 2)² = x² + 36 auf.", "o": {"wert": 8, "einheit": "m"}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Welche Zahl r muss rechts stehen, damit (x + 3)² = x² + r die Lösung x = 2 hat?"}, "w": "Einsetzen: (2 + 3)² = 25 und 2² + r = 4 + r. Also 4 + r = 25, r = 21.", "g": "umkehr", "h": "Setze x = 2 auf beiden Seiten ein.", "o": {"wert": 21}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Welcher Schritt kommt bei 2(x + 1)² = 2x² + 14 zuerst?"}, "w": "Erst (x + 1)² = x² + 2x + 1 ausmultiplizieren, dann mit 2 malnehmen.", "g": "darstellung", "h": "Potenz vor Punktrechnung.", "a": ["(x + 1)² ausmultiplizieren", "durch x teilen", "die Wurzel ziehen", "14 durch 2 teilen"], "o": {"index": 0}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Rechteck ist 3 cm länger als breit. Ein Quadrat hat die Breite als Seite. Das Rechteck ist 27 cm² größer als das Quadrat. Wie breit ist es?"}, "w": "x(x + 3) = x² + 27 ⇒ 3x = 27 ⇒ x = 9 cm.", "g": "rueckwaerts", "h": "Rechteck x(x + 3), Quadrat x².", "o": {"wert": 9, "einheit": "cm"}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Die Gleichung (x + 1)² = x² + 2x + 1 gilt für …"}, "w": "Beide Seiten sind gleich: Sie gilt für alle x.", "g": "begruenden", "h": "Multipliziere links aus.", "a": ["alle Zahlen x", "nur x = 0", "kein x", "nur x = 1"], "o": {"index": 0}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Lena löst (x + 3)² = x² + 15 so: x² + 9 = x² + 15 ⇒ 9 = 15, keine Lösung. Was stimmt?"}, "w": "Das Glied 6x fehlt. Richtig: 6x + 9 = 15 ⇒ x = 1.", "g": "fehler", "h": "Prüfe die binomische Formel.", "a": ["Falsch: richtig ist x = 1.", "Alles richtig.", "Falsch: richtig ist x = 6.", "Falsch: richtig ist x = 3."], "o": {"index": 0}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Löse (x + 2)² − (x − 2)² = 24."}, "w": "(x² + 4x + 4) − (x² − 4x + 4) = 8x = 24 ⇒ x = 3.", "g": "transfer", "h": "Beide Klammern ausmultiplizieren, dann abziehen.", "o": {"wert": 3}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "test", "s": 2, "y": "zahl", "f": {"text": "Löse (x + 5)² = x² + 45."}, "w": "10x + 25 = 45 ⇒ x = 2.", "o": {"wert": 2}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Löse (x + 1)² = x² + 13."}, "w": "2x + 1 = 13 ⇒ x = 6.", "o": {"wert": 6}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Löse (x + 4)² = x² + 40."}, "w": "8x + 16 = 40 ⇒ x = 3.", "o": {"wert": 3}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "korrektur", "s": 2, "y": "zahl", "f": {"text": "Löse (x + 6)² = x² + 84."}, "w": "12x + 36 = 84 ⇒ x = 4.", "o": {"wert": 4}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 2)² = x² + 28."}, "w": "4x + 4 = 28 ⇒ x = 6.", "o": {"wert": 6}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 3)² = x² + 45."}, "w": "6x + 9 = 45 ⇒ x = 6.", "o": {"wert": 6}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 5)² = x² + 65."}, "w": "10x + 25 = 65 ⇒ x = 4.", "o": {"wert": 4}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 1)² = x² + 7."}, "w": "2x + 1 = 7 ⇒ x = 3.", "o": {"wert": 3}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 4)² = x² + 56."}, "w": "8x + 16 = 56 ⇒ x = 5.", "o": {"wert": 5}}, {"l": "gleichungen_binomisch", "t": "gleichungen_binomisch", "p": "sicherung", "s": 2, "y": "zahl", "f": {"text": "Bestimme x aus (x + 2)² = x² + 16."}, "w": "4x + 4 = 16 ⇒ x = 3.", "o": {"wert": 3}}]$j$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(3, v_auf);
  raise notice 'Einheit 3 (gleichungen_binomisch): % von 22 Aufgaben eingefügt (0 = schon vorhanden)', v_n;
