end $lk$;

-- Thema 61 (stochastik.grundbegriffe), Einheit 31: Etappe darstellen „Baumdiagramm und Vierfeldertafel“ – 22 Aufgaben (uebung 12, test 1, korrektur 3, sicherung 6)
do $lk$
declare v_status text; v_inhalt jsonb; v_max int; v_auf jsonb; v_n int; v_geteilt boolean;
begin
