    update schule.einheit set inhalt = jsonb_set(jsonb_set(jsonb_set(inhalt,
        '{etappen}', coalesce(inhalt->'etappen', '[]'::jsonb) || jsonb_build_array($j${"lernziel": "irrational_beweis", "titel": "Warum √2 kein Bruch ist", "einstieg": "Der Taschenrechner zeigt √2 ≈ 1,41421356. Egal wie viele Stellen er anzeigt: Es gibt keinen Bruch, dessen Quadrat genau 2 ist. Das kann man nicht ausprobieren, man muss es beweisen – mit einem ⟦indirekten Beweis⟧.", "woerter": [["indirekter Beweis", "Man nimmt das Gegenteil an und zeigt, dass daraus ein Widerspruch folgt"], ["teilerfremd", "Zwei Zahlen haben außer 1 keinen gemeinsamen Teiler; jeder Bruch lässt sich so kürzen"]], "regel": "Indirekter Beweis: ⟦Gegenteil annehmen⟧, sauber weiterfolgern, auf einen Widerspruch stoßen. Dann war die Annahme falsch. Bei √2: Aus √2 = p/q (gekürzt) folgt, dass p und q beide gerade sind – das passt nicht zu „gekürzt“.", "schritte": [{"text": "Annahme: √2 = p/q, vollständig gekürzt."}, {"text": "Quadrieren: p² = 2q². Also ist p² gerade, und damit ist auch p gerade."}, {"text": "Mit p = 2r folgt q² = 2r²: Auch q ist gerade. ⟦Widerspruch⟧ zu „gekürzt“."}], "fehler": "Mit Beispielen „beweisen“: Dass 7/5 oder 141/100 nicht passen, zeigt nichts über alle Brüche. Erst der ⟦Widerspruch⟧ gilt für jeden Bruch."}$j$::jsonb)),
