  select jsonb_agg(x.a || jsonb_build_object('r', v_max + x.nr)) into v_auf
    from jsonb_array_elements($j$[{"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Womit beginnt ein indirekter Beweis für „√2 ist irrational“?"}, "w": "Man nimmt das Gegenteil an: √2 ist rational, also ein gekürzter Bruch p/q.", "g": "direkt", "h": "Gegenteil der Behauptung.", "a": ["Man rechnet √2 auf 10 Stellen aus.", "Annahme: √2 ist ein gekürzter Bruch p/q.", "Man probiert viele Brüche aus.", "Annahme: √2 ist irrational."], "o": {"index": 1}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Was folgt aus √2 = p/q durch Quadrieren?"}, "w": "(p/q)² = 2, also p²/q² = 2 und damit p² = 2q².", "g": "direkt", "h": "Beide Seiten quadrieren und mit q² malnehmen.", "a": ["p² = 2q²", "p = 2q", "p² = q² + 2", "2p = q²"], "o": {"index": 0}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Welche Aussage ist ein Widerspruch, wenn p/q vollständig gekürzt ist?"}, "w": "Gekürzt heißt teilerfremd; sind p und q beide gerade, hätten sie den Teiler 2.", "g": "erkennen", "h": "Was heißt „gekürzt“?", "a": ["p ist ungerade.", "q ist größer als 1.", "p und q sind beide gerade.", "p ist größer als q."], "o": {"index": 2}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 1, "y": "auswahl", "f": {"text": "Warum darf man am Anfang annehmen, dass p/q gekürzt ist?"}, "w": "Jeder Bruch lässt sich vollständig kürzen; wäre √2 ein Bruch, dann auch ein gekürzter.", "g": "erkennen", "h": "Kann man jeden Bruch kürzen?", "a": ["Weil √2 kleiner als 2 ist.", "Weil p und q gerade sind.", "Weil das im Taschenrechner so steht.", "Weil man jeden Bruch vollständig kürzen kann."], "o": {"index": 3}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade. (2) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (3) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (4) Quadrieren und umformen: 2 = p²/q², also p² = 2q².", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Richtig ist: Annahme, Quadrieren, beide gerade, Widerspruch.", "g": "mehrschritt", "h": "Was muss zuerst stehen?", "o": {"werte": [2, 4, 1, 3]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (2) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (3) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (4) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Reihenfolge: (3) Annahme, (2) p² = 2q², (4) beide gerade, (1) Widerspruch.", "g": "darstellung", "h": "Der Widerspruch steht am Ende.", "o": {"werte": [3, 2, 4, 1]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Aus p² = 2q² folgt „p² ist gerade“. Warum ist dann auch p gerade?"}, "w": "Wäre p ungerade, dann wäre auch p · p ungerade. Also muss p gerade sein.", "g": "umkehr", "h": "Ungerade mal ungerade ist …?", "a": ["Das Quadrat einer ungeraden Zahl ist ungerade.", "Weil 2 gerade ist.", "Weil q gerade ist.", "Weil jede Quadratzahl gerade ist."], "o": {"index": 0}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 2, "y": "luecken", "f": {"text": "Setze p = 2r in p² = 2q² ein und vereinfache.", "schablone": "q² = □ · r²", "hinweis": "eine ganze Zahl"}, "w": "(2r)² = 4r² = 2q², geteilt durch 2: q² = 2r².", "g": "einkleidung", "h": "Erst (2r)² ausrechnen.", "o": {"werte": [2]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Lena schreibt: „√2 = 1,414 ist ein endlicher Dezimalbruch, also rational. 1,414² = 1,999396 ≈ 2. Also stimmt die Annahme.“ Was ist falsch?"}, "w": "1,414 ist nur ein Näherungswert; 1,414² ist nicht genau 2. Ein Näherungswert sagt nichts über √2 selbst.", "g": "fehler", "h": "Ist 1,999396 genau 2?", "a": ["Sie hat falsch quadriert.", "1,414 ist nur ein Näherungswert, 1,414² ist nicht genau 2.", "Nichts, das ist ein Beweis.", "Dezimalbrüche sind nie rational."], "o": {"index": 1}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Tim beweist: „Aus p² = 2q² folgt p gerade. Also ist √2 irrational.“ Was fehlt?"}, "w": "Es fehlt der zweite Teil: auch q ist gerade. Erst dann entsteht der Widerspruch zu „gekürzt“.", "g": "rueckwaerts", "h": "Wo ist der Widerspruch?", "a": ["Der Nachweis, dass auch q gerade ist, und damit der Widerspruch.", "Nichts, der Beweis ist fertig.", "Eine Probe mit dem Taschenrechner.", "Dass p größer als q ist."], "o": {"index": 0}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Warum zeigt der Widerspruch, dass √2 irrational ist?"}, "w": "Aus der Annahme „√2 ist rational“ folgt etwas Unmögliches. Also ist die Annahme falsch, und √2 ist nicht rational.", "g": "begruenden", "h": "Was folgt, wenn eine Annahme zu etwas Unmöglichem führt?", "a": ["Weil p und q gerade sind.", "Weil √2 unendlich viele Stellen hat.", "Die Annahme „√2 ist rational“ führt zu etwas Unmöglichem, also ist sie falsch.", "Weil 2 eine Primzahl ist."], "o": {"index": 2}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Der gleiche Beweis klappt für √3 mit „durch 3 teilbar“ statt „gerade“. Für welche Zahl klappt er nicht, weil die Wurzel rational ist?"}, "w": "√9 = 3 ist rational; der Beweis scheitert, weil aus p² = 9q² nicht folgt, dass p und q beide durch 9 teilbar sind.", "g": "transfer", "h": "Welche Wurzel geht auf?", "a": ["√5", "√7", "√11", "√9"], "o": {"index": 3}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "test", "s": 2, "y": "auswahl", "f": {"text": "Welcher Schritt kommt im Beweis direkt nach „p² = 2q²“?"}, "w": "Aus p² = 2q² folgt, dass p² und damit p gerade ist.", "a": ["p ist gerade, also p = 2r.", "√2 ist irrational.", "Annahme: √2 = p/q.", "q ist ungerade."], "o": {"index": 0}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "korrektur", "s": 2, "y": "auswahl", "f": {"text": "Welche Begründung gehört zu diesem Schritt? „p² ist gerade, also ist p gerade.“"}, "w": "Begründung: Das Quadrat einer ungeraden Zahl ist ungerade. Die anderen Antworten begründen den Schritt nicht.", "a": ["Weil p² größer als p ist.", "Das Quadrat einer ungeraden Zahl ist ungerade.", "Weil 2 eine Primzahl ist.", "Weil der Taschenrechner das zeigt."], "o": {"index": 1}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "korrektur", "s": 2, "y": "auswahl", "f": {"text": "Welche Begründung gehört zu diesem Schritt? „Man darf p/q als gekürzt annehmen.“"}, "w": "Begründung: Jeder Bruch lässt sich vollständig kürzen. Die anderen Antworten begründen den Schritt nicht.", "a": ["Weil √2 kleiner als 2 ist.", "Jeder Bruch lässt sich vollständig kürzen.", "Weil q nicht 0 ist.", "Weil der Taschenrechner das zeigt."], "o": {"index": 1}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "korrektur", "s": 2, "y": "auswahl", "f": {"text": "Welche Begründung gehört zu diesem Schritt? „Aus q² = 2r² folgt: q ist gerade.“"}, "w": "Begründung: Wie bei p – q² ist gerade, also auch q. Die anderen Antworten begründen den Schritt nicht.", "a": ["Weil r gerade ist.", "Wie bei p – q² ist gerade, also auch q.", "Weil q kleiner als p ist.", "Weil der Taschenrechner das zeigt."], "o": {"index": 1}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (2) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (3) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade. (4) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [2, 1, 3, 4]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (2) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade. (3) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (4) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [1, 3, 2, 4]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (2) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (3) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (4) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [2, 3, 4, 1]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade. (2) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (3) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (4) Quadrieren und umformen: 2 = p²/q², also p² = 2q².", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [3, 4, 1, 2]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (2) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (3) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade. (4) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [4, 1, 3, 2]}}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "sicherung", "s": 2, "y": "luecken", "f": {"text": "Bringe die Beweisschritte für „√2 ist irrational“ in die richtige Reihenfolge. (1) Annahme: √2 ist rational, also √2 = p/q mit teilerfremden natürlichen Zahlen p und q. (2) Quadrieren und umformen: 2 = p²/q², also p² = 2q². (3) Widerspruch: p und q sind beide durch 2 teilbar, sie waren aber teilerfremd. Also ist √2 nicht rational. (4) p² ist gerade, also ist p gerade: p = 2r. Dann 4r² = 2q², also q² = 2r², und auch q ist gerade.", "schablone": "1. □ · 2. □ · 3. □ · 4. □", "hinweis": "Trage die Nummern der Schritte ein."}, "w": "Immer: Annahme gekürzter Bruch → p² = 2q² → p und q gerade → Widerspruch.", "o": {"werte": [1, 2, 4, 3]}}]$j$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(45, v_auf);
  raise notice 'Einheit 45 (irrational_beweis): % von 22 Aufgaben eingefügt (0 = schon vorhanden)', v_n;
  if v_n not in (0, 22) then raise exception 'Einheit 45 (irrational_beweis): nur % von 22 eingefügt – teilweise vorhanden, bitte prüfen', v_n; end if;
