  insert into schule.etappe_text (thema_id, lernziel, kann, geaendert_am) values (20, 'irrational_beweis', $j$Den indirekten Beweis für die Irrationalität von √2 in Schritten ordnen, begründen und Fehler darin finden$j$, now())
  on conflict (thema_id, lernziel) do nothing;
