-- Rauchtest (liest nur)
do $pruef$
declare v_et int; v_auf int; v_k int;
begin
  select count(*) into v_et from schule.einheit e, jsonb_array_elements(e.inhalt->'etappen') x where (e.id = 54 and x->>'lernziel' = 'vektor_koordinaten') or (e.id = 54 and x->>'lernziel' = 'vektor_drehen') or (e.id = 8 and x->>'lernziel' = 'streckung_vektor') or (e.id = 57 and x->>'lernziel' = 'vierecke_konstruieren') or (e.id = 93 and x->>'lernziel' = 'drachen_raute') or (e.id = 30 and x->>'lernziel' = 'wahre_groesse') or (e.id = 30 and x->>'lernziel' = 'koerper_symmetrie') or (e.id = 30 and x->>'lernziel' = 'raumwinkel') or (e.id = 94 and x->>'lernziel' = 'cavalieri') or (e.id = 3 and x->>'lernziel' = 'gleichungen_binomisch') or (e.id = 31 and x->>'lernziel' = 'darstellen') or (e.id = 45 and x->>'lernziel' = 'irrational_beweis');
  select count(*) into v_auf from schule.aufgabe a where (a.einheit_id = 54 and a.variante_gruppe = 'vektor_koordinaten') or (a.einheit_id = 54 and a.variante_gruppe = 'vektor_drehen') or (a.einheit_id = 8 and a.variante_gruppe = 'streckung_vektor') or (a.einheit_id = 57 and a.variante_gruppe = 'vierecke_konstruieren') or (a.einheit_id = 93 and a.variante_gruppe = 'drachen_raute') or (a.einheit_id = 30 and a.variante_gruppe = 'wahre_groesse') or (a.einheit_id = 30 and a.variante_gruppe = 'koerper_symmetrie') or (a.einheit_id = 30 and a.variante_gruppe = 'raumwinkel') or (a.einheit_id = 94 and a.variante_gruppe = 'cavalieri') or (a.einheit_id = 3 and a.variante_gruppe = 'gleichungen_binomisch') or (a.einheit_id = 31 and a.variante_gruppe = 'darstellen') or (a.einheit_id = 45 and a.variante_gruppe = 'irrational_beweis');
  select count(*) into v_k from schule.etappe_text where (thema_id = 46 and lernziel = 'vektor_koordinaten') or (thema_id = 46 and lernziel = 'vektor_drehen') or (thema_id = 47 and lernziel = 'streckung_vektor') or (thema_id = 44 and lernziel = 'vierecke_konstruieren') or (thema_id = 99 and lernziel = 'drachen_raute') or (thema_id = 91 and lernziel = 'wahre_groesse') or (thema_id = 91 and lernziel = 'koerper_symmetrie') or (thema_id = 91 and lernziel = 'raumwinkel') or (thema_id = 101 and lernziel = 'cavalieri') or (thema_id = 29 and lernziel = 'gleichungen_binomisch') or (thema_id = 61 and lernziel = 'darstellen') or (thema_id = 20 and lernziel = 'irrational_beweis');
  if v_et <> 12 then raise exception 'Rauchtest: % von 12 Etappen in den Einheiten', v_et; end if;
  if v_auf <> 264 then raise exception 'Rauchtest: % von 264 Aufgaben', v_auf; end if;
  if v_k <> 12 then raise exception 'Rauchtest: % von 12 Kann-Sätzen', v_k; end if;
  if exists (select 1 from schule.einheit where id in (3, 8, 30, 31, 45, 54, 57, 93, 94) and status <> 'freigegeben') then
    raise exception 'Rauchtest: eine Einheit ist nicht mehr freigegeben';
  end if;
  raise notice 'Rauchtest LK-D Einspiel bestanden: 12 Etappen, 264 Aufgaben, 12 Kann-Sätze';
end $pruef$;
